package com.ryanjei.orushio.pve.http;import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.application.*;import com.ryanjei.orushio.pve.domain.*;import com.ryanjei.orushio.pve.logging.AuditSink;import com.ryanjei.orushio.pve.map.*;import com.ryanjei.orushio.pve.persistence.ActiveSessionRepository;import com.ryanjei.orushio.pve.security.AuthService;import java.net.*;import java.net.http.*;import java.nio.file.Path;import java.time.Instant;import java.util.*;import org.junit.jupiter.api.*;
class MapAdminHttpServerTest{AdminHttpServer server;HttpClient client;String base,cookie,csrf;List<String> auditCodes=new ArrayList<>();FakeMaps maps=new FakeMaps();@BeforeEach void start()throws Exception{ServerAdministrationService admin=new ServerAdministrationService(){public List<OnlinePlayerView> onlinePlayers(){return List.of();}public boolean whitelistEnabled(){return false;}public boolean setWhitelistEnabled(boolean e){return e;}public List<WhitelistEntryView> whitelistedPlayers(){return List.of();}public WhitelistEntryView addWhitelistedPlayer(String n){throw new UnsupportedOperationException();}public void removeWhitelistedPlayer(String n){}};server=new AdminHttpServer(InetAddress.getByName("127.0.0.1"),0,new DefaultGameApplicationService(new MemorySession()),admin,maps,new AuthService(),Map::of,new AuditSink(){public void record(String a,String b,String c,String d){auditCodes.add(c);}public boolean healthy(){return true;}},false);server.start();client=HttpClient.newHttpClient();base="http://127.0.0.1:"+server.port();String token=server.issueBootstrapToken();var auth=client.send(HttpRequest.newBuilder(URI.create(base+"/auth/bootstrap")).header("X-Bootstrap-Token",token).POST(HttpRequest.BodyPublishers.noBody()).build(),HttpResponse.BodyHandlers.ofString());cookie=auth.headers().firstValue("Set-Cookie").orElseThrow().split(";",2)[0];csrf=extract(auth.body(),"csrfToken");}@AfterEach void stop(){server.close();}@Test void mapListAndEnableApisWork()throws Exception{assertEquals(200,get("/api/v1/maps").statusCode());var response=mutation("/api/v1/maps/enabled","PUT","{\"mapId\":\"map-a\",\"enabled\":true}");assertEquals(200,response.statusCode());assertTrue(maps.profile.enabled());}@Test void setupDetailsExposeCoordinatesAndMutationsAreAudited()throws Exception{String body=get("/api/v1/maps/setup").body();assertTrue(body.contains("\"label\":\"ファーム開始地点\""));assertTrue(body.contains("\"x\":120"));assertTrue(body.contains("\"minX\":10"));String request="{\"administrator\":\""+maps.admin+"\",\"field\":\"farmSpawn\",\"area\":false,\"index\":0}";assertEquals(200,mutation("/api/v1/maps/setup/teleport","POST",request).statusCode());assertEquals(200,mutation("/api/v1/maps/setup/entry","DELETE",request).statusCode());assertTrue(maps.teleported);assertTrue(maps.deleted);assertTrue(auditCodes.contains("MAP_SETUP_TELEPORTED"));assertTrue(auditCodes.contains("MAP_SETUP_ENTRY_DELETED"));}@Test void mapMutationRequiresAuthenticationAndCsrf()throws Exception{var unauth=HttpRequest.newBuilder(URI.create(base+"/api/v1/maps/setup/teleport")).header("Origin",base).header("X-CSRF-Token",csrf).POST(HttpRequest.BodyPublishers.ofString("{}")).build();assertEquals(401,client.send(unauth,HttpResponse.BodyHandlers.ofString()).statusCode());var bad=HttpRequest.newBuilder(URI.create(base+"/api/v1/maps/setup/entry")).header("Cookie",cookie).header("Origin",base).header("X-CSRF-Token","bad").method("DELETE",HttpRequest.BodyPublishers.ofString("{}")).build();assertEquals(403,client.send(bad,HttpResponse.BodyHandlers.ofString()).statusCode());}HttpResponse<String> get(String p)throws Exception{return client.send(HttpRequest.newBuilder(URI.create(base+p)).header("Cookie",cookie).GET().build(),HttpResponse.BodyHandlers.ofString());}HttpResponse<String> mutation(String p,String method,String body)throws Exception{return client.send(HttpRequest.newBuilder(URI.create(base+p)).header("Cookie",cookie).header("Origin",base).header("X-CSRF-Token",csrf).method(method,HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}static String extract(String json,String key){String marker="\""+key+"\":\"";int start=json.indexOf(marker)+marker.length();return json.substring(start,json.indexOf('"',start));}static final class MemorySession implements ActiveSessionRepository{GameSession value;public Optional<GameSession> load(){return Optional.ofNullable(value);}public void save(GameSession s){value=s;}}static final class FakeMaps implements MapAdministrationService{MapProfile profile=MapProfileTestSupport.complete();UUID admin=UUID.randomUUID();boolean deleted,teleported;public List<MapProfile> list(){return List.of(profile);}public Optional<String> fixedNextMapId(){return Optional.empty();}public MapProfile importZip(Path p,String i,String d){return profile;}public MapProfile setEnabled(String i,boolean e){profile=profile.withEnabled(e);return profile;}public void fixNext(String i){}public void delete(String i){}public SetupView startSetup(String i,UUID a,String s){return setup();}public SetupView setup(){Map<String,List<SetupEntry>> entries=Map.of("farmSpawn",List.of(new SetupEntry(new BlockPoint(120,64,-32,90,0),null)),"farmRegion",List.of(new SetupEntry(null,new Cuboid(10,60,10,30,70,30))));return new SetupView(true,"map-a","A",admin.toString(),"farmSpawn",false,List.of(),Map.of("farmSpawn",1,"farmRegion",1),entries);}public void selectField(UUID a,String f,boolean r){}public void recordClick(UUID a,BlockPoint p,boolean c){}public void removeSetupEntry(UUID a,String f,boolean r,int i){deleted=true;}public void teleportSetupEntry(UUID a,String f,boolean r,int i){teleported=true;}public MapProfile saveSetup(String s){return profile;}public void discardSetup(String s){}}static final class MapProfileTestSupport{static MapProfile complete(){BlockPoint p=new BlockPoint(0,0,0,0,0);Map<String,List<BlockPoint>> points=new HashMap<>();for(String k:MapProfile.REQUIRED_SINGLE_POINTS)points.put(k,List.of(p));points.put("normalCoreCandidates",List.of(p,p,p));points.put("shopPoints",List.of(p));Cuboid c=new Cuboid(0,0,0,1,1,1);Map<String,List<Cuboid>> areas=new HashMap<>();for(String k:MapProfile.REQUIRED_AREA_COUNTS.keySet())areas.put(k,List.of(c));return new MapProfile(new MapProfileId("map-a"),"A",false,"template",points,areas,Instant.now());}}}
